// examples/cardnews.py 가 만든 n8n_payload.json 을 검증합니다.
// 형식: {action, caption, media_files:[경로...]}
const p = $input.first().json.body ?? $input.first().json;
if (!p.caption) throw new Error('caption 없음 — cardnews.py 출력이 맞는지 확인하세요');
if (!Array.isArray(p.media_files) || p.media_files.length === 0) {
  throw new Error('media_files 비어 있음');
}
return [{ json: {
  caption: p.caption,
  files: p.media_files,
  count: p.media_files.length,
  action: p.action ?? 'AUTO_UPLOAD_INSTAGRAM',
} }];

// ⚠️ 발행 단계는 의도적으로 비워 뒀습니다.
// 인스타그램/스레드 발행은 계정 연동과 토큰이 필요하고, 사람마다 다릅니다.
// 이 노드를 지우고 아래 중 하나로 교체하세요:
//   - Instagram Graph API  (HTTP Request 노드)
//   - Buffer / Later 등 예약 발행 서비스
//   - Telegram/Slack 노드로 나에게 먼저 보내 눈으로 확인 후 수동 업로드
//
// 지금은 무엇이 발행될지 로그만 남깁니다. 안전한 기본값입니다.
const j = $input.first().json;
return [{ json: {
  status: 'DRY_RUN',
  message: `${j.count}장 준비됨. 발행 노드를 연결하세요.`,
  caption: j.caption,
  files: j.files,
} }];
